const crypto = require('crypto');
const item = $input.first();
const headers = Object.fromEntries(
  Object.entries(item.json.headers ?? {}).map(([key, value]) => [key.toLowerCase(), value])
);
const secret = String($env.N8N_CHATWOOT_WEBHOOK_SECRET || '');
const signatureHeader = headers['x-chatwoot-signature'];
const timestamp = String(headers['x-chatwoot-timestamp'] || '');
const reject = (reason, http_status = 401) => [{ json: { valid: false, reason, http_status } }];

if (!secret) return reject('Segredo do webhook do Chatwoot não configurado.', 503);
if (typeof signatureHeader !== 'string' || !/^sha256=[a-f0-9]{64}$/i.test(signatureHeader)) {
  return reject('Cabeçalho X-Chatwoot-Signature ausente ou malformado.');
}
if (!/^\d+$/.test(timestamp)) return reject('Cabeçalho X-Chatwoot-Timestamp ausente ou malformado.');
const seconds = Number(timestamp);
if (!Number.isSafeInteger(seconds) || Math.abs(Math.floor(Date.now() / 1000) - seconds) > 300) {
  return reject('Timestamp fora da janela de 5 minutos.');
}
let rawBody;
try {
  rawBody = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch {
  return reject('Corpo bruto indisponível. Habilite Raw Body no webhook.', 503);
}
const expected = crypto.createHmac('sha256', secret)
  .update(timestamp + '.', 'utf8').update(rawBody).digest();
const received = Buffer.from(signatureHeader.slice(7), 'hex');
if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
  return reject('Assinatura não confere.');
}
let body;
try {
  body = JSON.parse(rawBody.toString('utf8'));
} catch {
  return reject('Corpo assinado não contém JSON válido.', 400);
}
return [{ json: { valid: true, body } }];

const data = $('Normalizar evento Chatwoot').first().json;
return [{ json: {
  nome: data.nome,
  user_id_client: data.wa_user_id,
  telefone: data.telefone,
  remetente_id_use: data.wa_user_id,
  destinatario_id_use: data.numero_empresa,
  account_id: data.account_id,
  inbox_id: data.inbox_id,
  conversation_id: data.conversation_id
} }];

