const body = $('validar assinatura').first().json.body;
if (!body || typeof body !== 'object' || Array.isArray(body) || body.private === true) return [];

const isIncomingMessage = body.event === 'message_created' && body.message_type === 'incoming';
const isStatusUpdate = body.event === 'message_updated' && body.message_type === 'outgoing';
if (!isIncomingMessage && !isStatusUpdate) return [];

const conversation = body.conversation && typeof body.conversation === 'object' ? body.conversation : {};
const accountId = Number(body.account?.id ?? conversation.account_id);
const inboxId = Number(body.inbox?.id ?? conversation.inbox_id);
const conversationId = Number(conversation.id);
if (!Number.isSafeInteger(accountId) || !Number.isSafeInteger(inboxId) || !Number.isSafeInteger(conversationId)) {
  throw new Error('Evento Chatwoot sem account_id, inbox_id ou conversation_id válido.');
}

const configuredAccount = String($env.N8N_CHATWOOT_ACCOUNT_ID || '').trim();
if (!configuredAccount) throw new Error('Configure N8N_CHATWOOT_ACCOUNT_ID.');
if (String(accountId) !== configuredAccount) return [];

const configuredInboxes = String($env.N8N_CHATWOOT_INBOX_IDS || $env.N8N_CHATWOOT_INBOX_ID || '')
  .split(',').map((value) => value.trim()).filter(Boolean);
if (!configuredInboxes.length) throw new Error('Configure N8N_CHATWOOT_INBOX_IDS ou N8N_CHATWOOT_INBOX_ID.');
if (!configuredInboxes.includes(String(inboxId))) return [];

const channel = String(conversation.channel || '').trim();
if (!['Channel::WebWidget', 'Channel::Whatsapp'].includes(channel)) return [];

const sender = body.sender && typeof body.sender === 'object' ? body.sender : {};
const contact = conversation.meta?.sender && typeof conversation.meta.sender === 'object'
  ? conversation.meta.sender : sender;
const contactInboxSource = String(conversation.contact_inbox?.source_id || '').trim();
const contactId = String(contact.id || '').trim();
const externalContactId = contactInboxSource || contactId || String(conversationId);
const phone = String(contact.phone_number || '').replace(/\D/g, '');
const syntheticIdentity = 'chatwoot_' + accountId + '_' + inboxId + '_' + externalContactId.replace(/[^a-zA-Z0-9_.:-]/g, '_');

const userId = syntheticIdentity;
const telefone = phone || null;

const rawCreatedAt = body.created_at ?? body.updated_at;
const createdDate = typeof rawCreatedAt === 'number'
  ? new Date(rawCreatedAt < 1000000000000 ? rawCreatedAt * 1000 : rawCreatedAt)
  : new Date(rawCreatedAt);
if (!rawCreatedAt || Number.isNaN(createdDate.getTime())) throw new Error('Evento Chatwoot com data inválida.');

const conversationMessages = Array.isArray(conversation.messages) ? conversation.messages : [];
const matchingMessage = conversationMessages.find((message) => String(message.id) === String(body.id)) || {};
const rawStatus = String(body.status || matchingMessage.status || '').trim().toLowerCase();
const allowedStatuses = new Set(['sent', 'delivered', 'read', 'failed', 'progress']);
if (isStatusUpdate && !allowedStatuses.has(rawStatus)) return [];

const text = typeof body.content === 'string' ? body.content.trim() : '';
const attachments = Array.isArray(body.attachments) ? body.attachments : [];
const contentType = String(body.content_type || 'text').toLowerCase();
const supported = contentType === 'text' && attachments.length === 0 && text.length > 0;
const sourceId = String(body.source_id || matchingMessage.source_id || '').trim();
const incomingMessageId = sourceId || ('chatwoot_' + accountId + '_' + conversationId + '_' + String(body.id));
// As mensagens de saída são persistidas com o ID numérico devolvido pela API do Chatwoot.
const persistenceId = isStatusUpdate ? String(body.id) : incomingMessageId;
const businessNumber = String($env.N8N_WHATSAPP_BUSINESS_PHONE_NUMBER || '').replace(/\D/g, '');
const assignee = conversation.meta?.assignee || conversation.assignee || {};

return [{ json: {
  tipo_evento: isStatusUpdate ? 'status' : (supported ? 'mensagem' : 'nao_suportado'),
  mensagem_id: persistenceId,
  mensagem_persistencia_id: persistenceId,
  chatwoot_mensagem_id: body.id,
  account_id: accountId,
  inbox_id: inboxId,
  conversation_id: conversationId,
  canal: channel,
  nome: String(contact.name || 'N/A'),
  telefone,
  wa_user_id: userId,
  numero_empresa: businessNumber || ('chatwoot_inbox_' + inboxId),
  created_at: createdDate.toISOString(),
  status: isStatusUpdate ? rawStatus : null,
  tipo_mensagem: isStatusUpdate ? 'status' : (supported ? 'text' : 'unsupported'),
  texto: isIncomingMessage ? text : '',
  media_url: '',
  anexo_id: '',
  mime_type: '',
  origem: 'chatwoot',
  status_conversa: String(conversation.status || ''),
  assignee: { id: assignee.id ?? null, name: String(assignee.name || ''), type: String(assignee.type || '') },
  rejeicao: isIncomingMessage && !supported ? 'A Elo aceita somente mensagens de texto.' : ''
} }];

